gceDataSourceItem::gceDataSourceItem(gceWorkspaceItem *parent, const gce::datasrc_info &svc, gceContext &ctx) : gceWorkspaceItem(parent), m_cfg(svc)
{
    if (auto *schema = ctx.cfg.findDatasourceSchema(m_cfg.type))
    {
        m_icon1 = iconFromSVG(schema->m_svgIcon);
        m_icon0.CopyFromBitmap(wxBitmap(m_icon1).ConvertToDisabled());
    }
    else
    {
        gceContext::log_error("Datasource schema not found: {}", m_cfg.name);
    }
}
gceDataSourceItem::~gceDataSourceItem() {}

unsigned int gceDataSourceItem::getChildren(wxDataViewItemArray &array) const
{
    if (isConnectionOk())
    {
        array.Add(wxDataViewItem(m_tables.get()));
    }
    return static_cast<unsigned>(array.size());
}

wxIcon gceDataSourceItem::icon() const
{
    switch (m_status)
    {
    case gceEntityStatus::NONE:
        return m_icon0;
    case gceEntityStatus::OK:
        return m_icon1;
    case gceEntityStatus::FAILED:
        break;
    }
    return wxArtProvider::GetIcon(wxART_ERROR, wxART_MENU);
}

void gceDataSourceItem::onMenu(gceWorkspaceItemActionParams par)
{
    enum
    {
        Add = gceMenuCmds::IDM_ContextLow,
        Connect,
        Disconnect
    };
    gceMenuCmds menu;
    menu.add(Connect, "Connect").Enable(!isConnectionOk());
    menu.add(Disconnect, "Disconnect").Enable(isConnectionOk());
    menu.add(wxID_EDIT).Enable(!isConnectionOk());
    menu.add(wxID_DELETE).Enable(!isConnectionOk());
    auto selection = menu.GetPopupMenuSelectionFromUser(par.parent, Connect, Disconnect, wxID_SEPARATOR, wxID_EDIT, wxID_DELETE);
    if (selection == Connect)
    {
        doConnect(par.wsp);
    }
    else if (selection == Disconnect)
    {
        if (isConnectionOk())
        {
            udataConnectFinishMsg msg;
            msg.id_datasrc = m_cfg.id_datasrc;
            msg.sender = gce::queueId::WORKSPACE;
            par.wsp.ctx().postDataQueue(msg);
        }
    }
    else if (selection == wxID_EDIT)
    {
        auto [svctype, svcname, svcparams] = to_wxstring(m_cfg.type, m_cfg.name, m_cfg.params);
        bool autoConnect = m_cfg.autoConnect != 0;
        CConnect connd(svctype, svcname, svcparams, autoConnect, par.parent);
        if (connd.ShowModal() == wxID_OK)
        {
            std::tie(m_cfg.type, m_cfg.name, m_cfg.params) = to_string(svctype, svcname, svcparams);
            m_cfg.autoConnect = autoConnect ? 1 : 0;
            par.wsp.updateDataSource(m_cfg);
            par.model->ItemChanged(wxDataViewItem(this));
        }
    }
    else if (selection == wxID_DELETE)
    {
        par.wsp.removeDataSource(m_cfg);
        // actual delete is done later by message processor
    }
}
void gceDataSourceItem::processMsg(gceWorkspaceItemActionParams par, const gce::MessageInfo &msg)
{
    if (std::holds_alternative<udataConnectReplyMsg>(msg))
    {
        processConnectReplyMsg(par, std::get<udataConnectReplyMsg>(msg));
    }
    else if (m_tables)
    {
        m_tables->processMsg(par, msg);
    }
}

void gceDataSourceItem::processConnectReplyMsg(gceWorkspaceItemActionParams par, const udataConnectReplyMsg &msg)
{
    if (m_cfg.id_datasrc == msg.id_datasrc && m_status != msg.status)
    {
        m_status = msg.status;
        par.model->ItemChanged(wxDataViewItem(this));
        if (isConnectionOk())
        {
            m_tables = std::make_unique<gceTableGroup>(this, m_cfg);
            par.model->ItemAdded(wxDataViewItem(this), wxDataViewItem(m_tables.get()));

            m_tables->processInit(par);
        }
        else
        {
            if (m_tables)
            {
                par.model->ItemDeleted(wxDataViewItem(this), wxDataViewItem(m_tables.get()));
            }
            m_tables.reset();
        }
    }
}

void gceDataSourceItem::doConnect(gceWorkspace &wsp)
{
    if (!isConnectionOk())
    {
        udataConnectMsg msg{};
        msg.svcType = m_cfg.type;
        msg.connStr = m_cfg.params;
        msg.id_datasrc = m_cfg.id_datasrc;
        msg.sender = gce::queueId::WORKSPACE;
        wsp.ctx().postDataQueue(std::move(msg));
    }
}
